// Set, change, or turn off the PIN. Changing or removing always asks for the current PIN first.
function PinSetup({ currentPin, mode, onFinish, onCancel }) {
  const [stage, setStage] = useState(currentPin ? 'verify' : 'new');
  const [first, setFirst] = useState('');
  const [error, setError] = useState('');
  const titles = {
    verify: mode === 'remove' ? 'Enter your PIN to turn it off' : 'Enter your current PIN',
    new: currentPin ? 'Choose your new PIN' : 'Choose a 4-digit PIN',
    confirm: 'Enter it once more to confirm',
  };
  const subtitles = {
    verify: 'So we know it\'s really you.',
    new: 'Avoid easy ones like 1234 or your birth year.',
    confirm: 'Just making sure you remember it.',
  };
  const onComplete = (code) => {
    if (stage === 'verify') {
      if (code !== currentPin) { setError('That PIN is wrong — try again.'); return false; }
      setError('');
      if (mode === 'remove') { onFinish(''); return true; }
      setStage('new'); return true;
    }
    if (stage === 'new') { setError(''); setFirst(code); setStage('confirm'); return true; }
    if (code !== first) { setError("Those didn't match — choose your PIN again."); setFirst(''); setStage('new'); return false; }
    onFinish(code); return true;
  };
  return (
    <div className="fixed inset-0 z-[90]">
      <PinPad
        title={titles[stage]}
        subtitle={subtitles[stage]}
        error={error}
        onComplete={onComplete}
        top={<button onClick={onCancel} className="absolute left-5 flex items-center gap-1 text-[13px] font-medium min-h-[44px]" style={{ color: C.inkDim, top: 'max(14px, env(safe-area-inset-top))' }}><ChevronLeft size={18} /> Cancel</button>}
      />
    </div>
  );
}

// Oga's mark: the gold shard from the Xorla logo, cut like a gem. While Oga is working on an answer it spins,
// sparks circle it and light sweeps across it, so you can see it thinking.
const OGA_GEM = 'M6 10 L34 10 L34 29 L16 29 Z';
function OgaMark({ size = 18, thinking = false, tone = 'gold', className = '', style }) {
  const id = 'og' + React.useId().replace(/:/g, '');
  const ink = tone === 'ink';
  if (tone === 'mono') {
    // Plain version for menus: takes the colour of the text around it, like every other icon there
    return (
      <svg width={size} height={size} viewBox="0 0 40 40" fill="none" aria-hidden className={`oga-mark ${thinking ? 'oga-thinking' : ''} ${className}`} style={{ flexShrink: 0, overflow: 'visible', ...style }}>
        <g className="oga-gem">
          <path d={OGA_GEM} stroke="currentColor" strokeWidth="3" strokeLinejoin="round" />
          <path d="M6 10 L23.5 17.5 L34 10" stroke="currentColor" strokeWidth="2.4" strokeLinejoin="round" opacity="0.75" />
          <path d="M23.5 17.5 L25 29" stroke="currentColor" strokeWidth="2.4" opacity="0.75" />
        </g>
      </svg>
    );
  }
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" fill="none" aria-hidden className={`oga-mark ${thinking ? 'oga-thinking' : ''} ${className}`} style={{ flexShrink: 0, overflow: 'visible', ...style }}>
      <defs>
        <linearGradient id={`${id}g`} x1="6" y1="8" x2="34" y2="31" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor={ink ? '#2A6B5F' : '#FFDB8A'} />
          <stop offset="0.5" stopColor={ink ? '#0E3C34' : '#FFB020'} />
          <stop offset="1" stopColor={ink ? '#06201C' : '#E08700'} />
        </linearGradient>
        <linearGradient id={`${id}s`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#fff" stopOpacity="0" /><stop offset="0.5" stopColor="#fff" stopOpacity="0.8" /><stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        <clipPath id={`${id}c`}><path d={OGA_GEM} /></clipPath>
      </defs>
      <g className="oga-orbit">
        <circle cx="20" cy="1.5" r="2" fill="#1FD9C4" />
        <circle cx="36.5" cy="29" r="1.5" fill={ink ? '#FFB020' : '#FFB020'} />
        <circle cx="3.5" cy="29" r="1.2" fill="#1FD9C4" opacity="0.8" />
      </g>
      <g className="oga-gem">
        <path d={OGA_GEM} fill={`url(#${id}g)`} />
        <path d="M6 10 L34 10 L23.5 17.5 Z" fill="#fff" opacity={ink ? 0.16 : 0.32} />
        <path d="M16 29 L34 29 L34 18.5 L25 21 Z" fill="#000" opacity="0.12" />
        <g clipPath={`url(#${id}c)`}><rect className="oga-sheen" x="-14" y="4" width="10" height="32" fill={`url(#${id}s)`} /></g>
      </g>
    </svg>
  );
}
